#!/usr/bin/env bash
# Question 1: Unhealthy worker. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "ops" >/dev/null 2>&1 || kubectl get namespace "ops" >/dev/null
timeout 60 bash -c "until kubectl -n 'ops' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: DaemonSet
metadata:
  name: node-probe
  namespace: ops
spec:
  selector:
    matchLabels: { app: node-probe }
  template:
    metadata:
      labels: { app: node-probe }
    spec:
      containers:
        - name: probe
          image: registry.k8s.io/pause:3.10
          resources:
            requests: { cpu: 10m, memory: 8Mi }
EOF
kubectl -n "ops" rollout status daemonset/node-probe --timeout=240s

(
case "${Q1_FAULT}" in
  containerd-stopped) ;;
  ip-forward-and-containerd) ;;
  cni-config-removed) ;;
  containerd-config-invalid) ;;
  cni-conflist-typo) ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q1_FAULT_2}" in
  kubelet-stopped) ;;
  kubelet-binary-path) ;;
  kubelet-config-invalid) ;;
  kubelet-client-ca) ;;
  kubelet-api-port) ;;
  kubelet-extra-args) ;;
  kubelet-conf-missing) ;;
  kubelet-swap-on) ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q1_FAULT_3}" in
  cordoned)
    kubectl cordon "${Q1_NODE}"
    ;;
  stray-taint)
    kubectl taint node "${Q1_NODE}" maintenance=true:NoSchedule --overwrite
    kubectl -n "ops" delete pod -l app=node-probe --field-selector "spec.nodeName=${Q1_NODE}" --wait=false
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)
